      events: fresh.map((x) => ({
        origin_id: x.id,
        origin_type: "article_published",
        title: x.title ?? x.url,
        author_name: x.author,
        source_url: x.url,
        occurred_at: x.publishedDate ? new Date(x.publishedDate) : new Date(),
      })),
      checkpoint: { seen_ids: [...seen, ...fresh.map((x) => x.id)].slice(-1000) },
    };
  }

  async execute() {
    return { success: false, error: "no actions" };
  }
}
